<template>
  <div class="extraction-weight-history" :title="tooltip">
    <span
      v-for="(dot, index) in dots"
      :key="index"
      class="extraction-weight-history__dot"
      :class="`extraction-weight-history__dot--${dot.color}`"
      :style="{ opacity: dot.intensity }"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { mapWeightHistoryToDots } from 'src/utils/extraction-score-formatter';

export default defineComponent({
  name: 'ExtractionWeightHistory',
  props: {
    /** lastFiveWeights from FellowKVRuleWeight, oldest first */
    history: {
      type: Array as () => number[],
      default: () => [],
    },
    /** sample_size for the tooltip "Saved 47 times" */
    sampleSize: { type: Number, default: 0 },
  },
  setup(props) {
    const dots = computed(() => mapWeightHistoryToDots(props.history));
    const tooltip = computed(() => {
      const samples = props.history?.length ?? 0;
      return `Last ${samples} training sample${samples === 1 ? '' : 's'} (sample size ${props.sampleSize})`;
    });
    return { dots, tooltip };
  },
});
</script>

