import { ref, computed } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import { useAuthTokenStore } from 'src/store/main';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type ExtractionExplanationApiService from 'src/services/document/ExtractionExplanationApiService';
import type {
  DocumentExtractionExplanations,
  FieldExplanation,
} from 'src/types/extractionExplanation';

/**
 * Live-syncs per-field extraction explanations for a document via Server-Sent
 * Events. Subscribes to the backend stream
 * (`GET /documents/{id}/extraction-explanations/stream`) and writes incoming
 * payloads into a reactive ref. Vue's existing reactivity re-renders the
 * panel — **no page reload, no router navigation, no DOM manipulation
 * outside Vue.**
 *
 * The legacy `load(docId)` / `refresh()` HTTP fallback is preserved for
 * environments where SSE is blocked (corporate proxies, certain test
 * harnesses) — when SSE fails to connect twice in a row, the consumer can
 * still call `load()` to get the current snapshot.
 */
export function useExtractionExplanation(
  apiService: ExtractionExplanationApiService,
) {
  const data = ref<DocumentExtractionExplanations | null>(null);
  const loading = ref(false);
  /**
   * On error, holds an i18n key the panel translates with $t. We do not
   * surface the raw API message because backend 5xx text can be technical
   * or leak internals; the original error is logged via logError.
   */
  const error = ref<string | null>(null);
  const lastLoadedDocId = ref<string | null>(null);
  // Monotonic request token. Only the response of the *latest* in-flight
  // load() / subscribe() is allowed to mutate state — older responses
  // (slow network, user navigated to another doc) are dropped to prevent
  // flicker and stale-data writes.
  let requestToken = 0;
  // SSE state
  let abortController: AbortController | null = null;
  let reconnectTimeout: ReturnType<typeof setTimeout> | null = null;
  // Backoff for reconnects: 1s, 2s, 4s, 8s, capped at 30s. Reset to 1s on
  // every successful snapshot.
  let reconnectDelayMs = 1000;
  const RECONNECT_MAX_DELAY_MS = 30000;

  // ─── Legacy one-shot HTTP load (kept as fallback) ────────────────────
  async function load(docId: string, force = false): Promise<void> {
    if (!docId) {
      requestToken += 1;
      data.value = null;
      lastLoadedDocId.value = null;
      return;
    }

    if (!force && lastLoadedDocId.value === docId && data.value !== null) {
      return;
    }

    const myToken = ++requestToken;
    loading.value = true;
    error.value = null;
    try {
      const response = await apiService.getForDocument(docId);
      if (myToken !== requestToken) return;
      data.value = response;
      lastLoadedDocId.value = docId;
    } catch (err) {
      if (myToken !== requestToken) return;
      data.value = null;
      lastLoadedDocId.value = null;
      error.value = 'extraction_insights.error_load_failed';
      logError('useExtractionExplanation.load failed', { docId, err });
    } finally {
      if (myToken === requestToken) {
        loading.value = false;
      }
    }
  }

  function refresh(): Promise<void> {
    return lastLoadedDocId.value
      ? load(lastLoadedDocId.value, true)
      : Promise.resolve();
  }

  // ─── Live SSE subscription (preferred) ───────────────────────────────
  /**
   * Open the SSE stream for `docId`. Closes any previous stream first.
   * Triggers automatic reconnect on transport failure; cancellation is
   * silent (AbortError is not surfaced to the user).
   */
  async function subscribe(docId: string): Promise<void> {
    unsubscribe();
    if (!docId) {
      data.value = null;
      lastLoadedDocId.value = null;
      return;
    }

    const myToken = ++requestToken;
    loading.value = true;
    error.value = null;
    reconnectDelayMs = 1000;
    await openStream(docId, myToken);
  }

  /**
   * Stop listening to the SSE stream and cancel any pending reconnect.
   * Safe to call multiple times. Does not clear `data` so the panel keeps
   * showing the last-known state after the user navigates away briefly.
   */
  function unsubscribe(): void {
    requestToken += 1; // invalidate any in-flight handler
    if (reconnectTimeout) {
      clearTimeout(reconnectTimeout);
      reconnectTimeout = null;
    }
    if (abortController) {
      abortController.abort();
      abortController = null;
    }
  }

  function clear(): void {
    unsubscribe();
    data.value = null;
    lastLoadedDocId.value = null;
    error.value = null;
  }

  async function openStream(docId: string, myToken: number): Promise<void> {
    if (myToken !== requestToken) return; // a newer subscribe() already ran

    const authStore = useAuthTokenStore();
    const token = authStore.token;
    const orgId = getOrgId();
    if (!token || !orgId) {
      error.value = 'extraction_insights.error_load_failed';
      loading.value = false;
      return;
    }

    abortController = new AbortController();
    const url = `${DOC2API_URL}/documents/${encodeURIComponent(docId)}/extraction-explanations/stream`;

    let response: Response;
    try {
      response = await fetch(url, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'X-ORG-ID': orgId,
          Accept: 'text/event-stream',
          'Cache-Control': 'no-cache',
        },
        signal: abortController.signal,
      });
    } catch (fetchErr) {
      if ((fetchErr as Error).name === 'AbortError') return;
      handleStreamFailure(docId, myToken, fetchErr as Error);
      return;
    }

    if (myToken !== requestToken) return;

    if (!response.ok || !response.body) {
      // Surface auth/perm failures verbatim so the panel can show the
      // right message; transport errors trigger reconnect via the catch
      // path below.
      const status = response.status;
      if (status === 401 || status === 403 || status === 404) {
        error.value = 'extraction_insights.error_load_failed';
        loading.value = false;
        return;
      }
      handleStreamFailure(
        docId,
        myToken,
        new Error(`stream open failed: ${status}`),
      );
      return;
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    try {
      // Read loop. Each iteration appends decoded bytes to a small buffer
      // and slices off complete events ("\n\n" separator). Vue refs are
      // updated synchronously inside applyEvent — no page reload, no
      // router navigation, just normal reactive writes.
      // eslint-disable-next-line no-constant-condition
      while (true) {
        if (myToken !== requestToken) return;
        const { value, done } = await reader.read();
        if (done) {
          break;
        }
        buffer += decoder.decode(value, { stream: true });
        let separatorIndex = buffer.indexOf('\n\n');
        while (separatorIndex !== -1) {
          const rawEvent = buffer.slice(0, separatorIndex);
          buffer = buffer.slice(separatorIndex + 2);
          applyEvent(rawEvent, docId, myToken);
          separatorIndex = buffer.indexOf('\n\n');
        }
      }
    } catch (readErr) {
      if ((readErr as Error).name === 'AbortError') return;
      handleStreamFailure(docId, myToken, readErr as Error);
      return;
    }

    // Server closed the stream cleanly — try to reconnect (e.g. after
    // the 30-min hard lifetime cap in the backend).
    if (myToken === requestToken) {
      handleStreamFailure(docId, myToken, new Error('stream ended by server'));
    }
  }

  function applyEvent(rawEvent: string, docId: string, myToken: number): void {
    if (myToken !== requestToken) return;
    if (!rawEvent.trim()) return;

    let eventName = 'message';
    const dataLines: string[] = [];
    for (const line of rawEvent.split('\n')) {
      if (line.startsWith(':')) {
        // SSE comment (heartbeat). Ignore.
        continue;
      }
      if (line.startsWith('event:')) {
        eventName = line.slice(6).trim();
      } else if (line.startsWith('data:')) {
        dataLines.push(line.slice(5).trim());
      }
    }
    if (dataLines.length === 0) return;

    const dataPayload = dataLines.join('\n');

    if (eventName === 'snapshot' || eventName === 'update' || eventName === 'message') {
      try {
        const parsed = JSON.parse(dataPayload) as DocumentExtractionExplanations;
        data.value = parsed;
        lastLoadedDocId.value = docId;
        loading.value = false;
        error.value = null;
        reconnectDelayMs = 1000; // reset backoff after any successful payload
      } catch (parseErr) {
        logError('useExtractionExplanation.applyEvent JSON parse failed', {
          docId,
          parseErr,
          payload: dataPayload.slice(0, 200),
        });
      }
      return;
    }

    if (eventName === 'error') {
      error.value = 'extraction_insights.error_load_failed';
      loading.value = false;
      logError('useExtractionExplanation stream error event', {
        docId,
        payload: dataPayload,
      });
      return;
    }

    if (eventName === 'close') {
      // Server wants us to drop the connection (max lifetime). The reader
      // loop will end naturally and trigger reconnect via the post-loop
      // handleStreamFailure call.
      return;
    }
  }

  function handleStreamFailure(
    docId: string,
    myToken: number,
    err: Error,
  ): void {
    if (myToken !== requestToken) return; // a newer subscribe replaced us

    logError('useExtractionExplanation stream failure', {
      docId,
      message: err.message,
      retryInMs: reconnectDelayMs,
    });

    if (reconnectTimeout) clearTimeout(reconnectTimeout);
    const delay = reconnectDelayMs;
    reconnectDelayMs = Math.min(reconnectDelayMs * 2, RECONNECT_MAX_DELAY_MS);
    reconnectTimeout = setTimeout(() => {
      void openStream(docId, myToken);
    }, delay);
  }

  const fields = computed<FieldExplanation[]>(
    () => data.value?.fields ?? [],
  );

  return {
    data,
    fields,
    loading,
    error,
    // Live sync (preferred path)
    subscribe,
    unsubscribe,
    // Legacy / manual paths (kept for compat + fallback)
    load,
    refresh,
    clear,
  };
}
