<template>
  <div class="extraction-insights-panel">
    <div class="extraction-insights-panel__header">
      <h3 class="extraction-insights-panel__title">
        {{ $t('extraction_insights.title') }}
      </h3>
      <q-btn
        flat
        dense
        round
        icon="mdi:refresh"
        size="sm"
        :loading="loading"
        @click="reload"
      >
        <q-tooltip>{{ $t('extraction_insights.refresh') }}</q-tooltip>
      </q-btn>
    </div>

    <div v-if="fields.length > 0" class="extraction-insights-panel__filters">
      <q-chip
        clickable
        dense
        size="sm"
        :outline="selectedField !== ''"
        :color="selectedField === '' ? 'primary' : undefined"
        :text-color="selectedField === '' ? 'white' : undefined"
        :label="$t('extraction_insights.filter.all')"
        @click="selectedField = ''"
      />
      <q-chip
        v-for="name in fieldNames"
        :key="name"
        clickable
        dense
        size="sm"
        :outline="selectedField !== name"
        :color="selectedField === name ? 'primary' : undefined"
        :text-color="selectedField === name ? 'white' : undefined"
        :label="name"
        @click="selectedField = name"
      />
    </div>

    <div v-if="loading" class="extraction-insights-panel__state">
      <q-spinner size="sm" />
      <span>{{ $t('extraction_insights.loading') }}</span>
    </div>

    <div v-else-if="error" class="extraction-insights-panel__state extraction-insights-panel__state--error">
      <q-icon name="mdi:alert-circle" />
      <span>{{ $t(error) }}</span>
    </div>

    <div v-else-if="visibleFields.length === 0" class="extraction-insights-panel__state">
      <q-icon name="mdi:information-outline" />
      <span>{{ $t('extraction_insights.empty') }}</span>
    </div>

    <div v-else class="extraction-insights-panel__list">
      <ExtractionFieldCard
        v-for="field in visibleFields"
        :key="field.field_name"
        :field="field"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch, onMounted, onUnmounted } from 'vue';
import ExtractionFieldCard from 'src/components/document/ExtractionFieldCard.vue';
import { useExtractionExplanation } from 'src/composables/useExtractionExplanation';
import ExtractionExplanationApiService from 'src/services/document/ExtractionExplanationApiService';

export default defineComponent({
  name: 'ExtractionInsightsPanel',
  components: { ExtractionFieldCard },
  props: {
    docId: { type: String, required: true },
  },
  setup(props) {
    const apiService = new ExtractionExplanationApiService({});
    const { fields, loading, error, subscribe, unsubscribe, refresh } =
      useExtractionExplanation(apiService);

    const selectedField = ref('');

    const fieldNames = computed(() =>
      fields.value.map((f) => f.field_name).filter(Boolean),
    );

    const visibleFields = computed(() => {
      if (!selectedField.value) return fields.value;
      return fields.value.filter((f) => f.field_name === selectedField.value);
    });

    function reload() {
      // Manual reload button still works even with SSE — it forces a
      // single GET via the legacy fallback. Useful if the user feels the
      // stream is stuck (edge case during proxy hiccups).
      void refresh();
    }

    onMounted(() => {
      // Live SSE subscription. Vue ref updates on every push — no page
      // reload, no router navigation.
      void subscribe(props.docId);
    });

    onUnmounted(() => {
      unsubscribe();
    });

    watch(
      () => props.docId,
      (newId, oldId) => {
        if (newId && newId !== oldId) {
          selectedField.value = '';
          void subscribe(newId);
        }
      },
    );

    return {
      fields,
      visibleFields,
      fieldNames,
      selectedField,
      loading,
      error,
      reload,
    };
  },
});
</script>

