<template>
  <div class="extraction-score-bar">
    <div class="extraction-score-bar__row">
      <span class="extraction-score-bar__label">{{ label }}</span>
      <div class="extraction-score-bar__track">
        <div
          class="extraction-score-bar__fill"
          :class="`extraction-score-bar__fill--${color}`"
          :style="{ width: `${pct}%` }"
        />
      </div>
      <span class="extraction-score-bar__value">{{ value }}/{{ max }}</span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';

export default defineComponent({
  name: 'ExtractionScoreBar',
  props: {
    label: { type: String, required: true },
    value: { type: Number, required: true },
    max: { type: Number, required: true },
    color: {
      type: String as () => 'primary' | 'positive' | 'warning' | 'negative',
      default: 'primary',
    },
  },
  setup(props) {
    const pct = computed(() => {
      if (props.max <= 0) return 0;
      const ratio = (props.value / props.max) * 100;
      return Math.max(0, Math.min(100, ratio));
    });
    return { pct };
  },
});
</script>

