<template>
  <div
    class="extraction-field-card"
    :class="{ 'extraction-field-card--dirty': isDirty }"
  >
    <div class="extraction-field-card__header">
      <div class="extraction-field-card__title">
        <span class="extraction-field-card__name">{{ field.field_name }}</span>
        <span v-if="field.extracted_value" class="extraction-field-card__value">
          {{ field.extracted_value }}
        </span>
      </div>
      <div class="extraction-field-card__chips">
        <q-chip
          v-if="isDirty"
          dense
          size="xs"
          color="warning"
          text-color="white"
          icon="mdi:circle-edit-outline"
          :label="$t('extraction_insights.pending_save')"
        />
        <q-chip
          dense
          size="sm"
          :color="methodChipColor"
          text-color="white"
          :label="methodLabel"
        />
      </div>
    </div>
    <p v-if="isDirty" class="extraction-field-card__pending-hint">
      {{ $t('extraction_insights.pending_save_hint') }}
    </p>

    <template v-if="field.trainable">
      <div
        v-for="candidate in field.candidates"
        :key="candidate.rule_id || candidate.rank"
        class="extraction-field-card__candidate"
        :class="{ 'extraction-field-card__candidate--winner': candidate.is_winner }"
      >
        <div class="extraction-field-card__candidate-header">
          <q-icon
            v-if="candidate.is_winner"
            name="mdi:trophy"
            size="14px"
            color="positive"
          />
          <span class="extraction-field-card__candidate-label">
            {{ candidateTitle(candidate) }}
          </span>
          <span class="extraction-field-card__candidate-score">
            {{ $t('extraction_insights.score.label') }} {{ candidate.score }}
          </span>
        </div>

        <template v-if="!isLegacyBreakdown(candidate)">
          <ExtractionScoreBar
            :label="$t('extraction_insights.score.label_match')"
            :value="candidate.score_breakdown.label"
            :max="40"
            color="primary"
          />
          <ExtractionScoreBar
            :label="$t('extraction_insights.score.coordinates')"
            :value="candidate.score_breakdown.coordinates"
            :max="40"
            color="primary"
          />
          <ExtractionScoreBar
            :label="$t('extraction_insights.score.weight')"
            :value="candidate.score_breakdown.weight"
            :max="20"
            color="primary"
          />
          <ExtractionScoreBar
            :label="$t('extraction_insights.score.context_pattern')"
            :value="candidate.score_breakdown.context_pattern"
            :max="30"
            color="primary"
          />
        </template>
        <p v-else class="extraction-field-card__legacy-hint">
          {{ $t('extraction_insights.no_breakdown_legacy') }}
        </p>

        <div v-if="hasPosition(candidate) || candidate.position_match !== 'no_position'" class="extraction-field-card__meta">
          <q-chip
            v-if="hasPosition(candidate)"
            dense
            outline
            size="xs"
            color="primary"
            icon="mdi:crosshairs-gps"
            :label="positionLabel(candidate)"
            class="extraction-field-card__position-chip"
          >
            <q-tooltip>{{ $t('extraction_insights.position') }}</q-tooltip>
          </q-chip>
          <q-chip
            v-if="candidate.position_match === 'different_position'"
            dense
            size="xs"
            color="warning"
            text-color="white"
            :label="$t('extraction_insights.position_different')"
          />
          <q-chip
            v-else-if="candidate.position_match === 'matched'"
            dense
            size="xs"
            color="positive"
            text-color="white"
            :label="$t('extraction_insights.position_matched')"
          />
        </div>

        <div class="extraction-field-card__training">
          <ExtractionWeightHistory
            :history="candidate.weight_history"
            :sample-size="candidate.sample_size"
          />
          <span class="extraction-field-card__training-text">
            <template v-if="hasTraining(candidate)">
              {{
                $t('extraction_insights.saved_times', { count: candidate.sample_size })
              }}
              —
              {{ $t(`extraction_insights.weight.${weightTier(candidate)}`) }}
            </template>
            <template v-else>
              {{ $t('extraction_insights.not_yet_trained') }}
            </template>
          </span>
        </div>
        <div
          v-if="trainedByLabel(candidate)"
          class="extraction-field-card__trainer"
        >
          <q-icon name="mdi:account-circle-outline" size="14px" />
          <span>
            {{ $t('extraction_insights.trained_by') }}
            <strong>{{ trainedByLabel(candidate) }}</strong>
          </span>
        </div>
      </div>

      <div v-if="field.candidates.length === 0" class="extraction-field-card__empty">
        {{ $t('extraction_insights.no_rule') }}
      </div>
    </template>

    <template v-else>
      <div class="extraction-field-card__non-trainable">
        <ExtractionScoreBar
          :label="$t('extraction_insights.score.final_confidence')"
          :value="field.final_confidence"
          :max="100"
          color="primary"
        />
        <p class="extraction-field-card__explanation">
          {{ $t(field.explanation_key || 'extraction_insights.no_rule') }}
        </p>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed, onMounted, onUnmounted, type PropType } from 'vue';
import ExtractionScoreBar from 'src/components/document/ExtractionScoreBar.vue';
import ExtractionWeightHistory from 'src/components/document/ExtractionWeightHistory.vue';
import { useDocumentStore } from 'src/store/main';
import {
  formatPosition,
  qualitativeWeight,
  type WeightTier,
} from 'src/utils/extraction-score-formatter';
import type {
  CandidateRule,
  FieldExplanation,
} from 'src/types/extractionExplanation';

export default defineComponent({
  name: 'ExtractionFieldCard',
  components: { ExtractionScoreBar, ExtractionWeightHistory },
  props: {
    field: {
      type: Object as PropType<FieldExplanation>,
      required: true,
    },
  },
  setup(props) {
    const documentStore = useDocumentStore();
    // Bump on every `field_value_updated` to force the isDirty computed
    // to re-evaluate (the underlying `checkifFieldChanged` reads from
    // SessionStorage which Vue cannot track natively).
    const dirtyTick = ref(0);

    function bumpDirty() {
      dirtyTick.value += 1;
    }

    onMounted(() => {
      document.addEventListener('field_value_updated', bumpDirty);
    });
    onUnmounted(() => {
      document.removeEventListener('field_value_updated', bumpDirty);
    });

    const isDirty = computed(() => {
      // Read dirtyTick to register a reactive dependency — the actual
      // value is irrelevant. checkifFieldChanged returns true when the
      // current form value differs from the last-saved snapshot.
      void dirtyTick.value;
      const name = props.field.field_name;
      if (!name) return false;
      try {
        return Boolean(documentStore.checkifFieldChanged(name));
      } catch {
        // Edge: store not yet hydrated. Fail closed so we don't show a
        // misleading "Pending save" badge before the form even loaded.
        return false;
      }
    });

    return { isDirty };
  },
  computed: {
    methodLabel(): string {
      return this.field.extraction_method;
    },
    methodChipColor(): string {
      const method = (this.field.extraction_method || '').toUpperCase();
      if (method === 'AI') return 'purple';
      if (method === 'ELECTRONIC_DOCUMENT') return 'teal';
      if (method === 'CALCULATED') return 'indigo';
      return 'primary';
    },
  },
  methods: {
    candidateTitle(candidate: CandidateRule): string {
      // Prefer the original training literal — "Invoice #:" left-side label
      // — over the generated regex which is unreadable to users.
      // See doc2-api PR #9343 for the word_left/word_above backend addition.
      if (candidate.word_left) {
        return `"${candidate.word_left}" left-side label`;
      }
      if (candidate.word_above) {
        return `"${candidate.word_above}" above`;
      }
      // Backwards-compat fallback: a label (regex) without the original word —
      // hide the regex itself, just show position context so users see
      // something meaningful instead of \p{L}-noise.
      if (candidate.label_left) return 'Left-side label';
      if (candidate.label_above) return 'Label above';
      if (candidate.label_right) return 'Right-side label';
      if (candidate.label_below) return 'Label below';
      return `Rule ${candidate.rank}`;
    },
    positionLabel(candidate: CandidateRule): string {
      const formatted = formatPosition(candidate.coords);
      return formatted || '—';
    },
    hasPosition(candidate: CandidateRule): boolean {
      return Boolean(formatPosition(candidate.coords));
    },
    /**
     * Detect legacy candidates: extraction happened before Phase 2 deploy
     * so the per-component score breakdown was never persisted. The aggregate
     * score is non-zero but every sub-score is 0 — showing "Label 0/40,
     * Coordinates 0/40" would be misleading because the bars contradict the
     * displayed final score. We hide the bars and show an explanatory hint.
     */
    isLegacyBreakdown(candidate: CandidateRule): boolean {
      const b = candidate.score_breakdown;
      const allZero =
        b.label === 0 &&
        b.coordinates === 0 &&
        b.weight === 0 &&
        b.context_pattern === 0;
      return allZero && candidate.score > 0;
    },
    /**
     * Hide the "Saved 0 times — low weight" line when the rule has never been
     * trained: that text reads like an informative state but really conveys
     * "no data". Show "Not yet trained" instead.
     */
    hasTraining(candidate: CandidateRule): boolean {
      return candidate.sample_size > 0;
    },
    weightTier(candidate: CandidateRule): WeightTier {
      return qualitativeWeight(candidate.current_aggregated_weight);
    },
    /**
     * Display label for the rule trainer. Order of preference:
     *  1. "First Last" if the cached UsersCache has both name parts
     *  2. email
     *  3. null → footer line is hidden (no leakage of "system" or
     *     "unknown" because we have nothing useful to say)
     */
    trainedByLabel(candidate: CandidateRule): string | null {
      if (
        candidate.trained_by_name &&
        candidate.trained_by_name.trim().length > 0
      ) {
        return candidate.trained_by_name;
      }
      if (
        candidate.trained_by_email &&
        candidate.trained_by_email.trim().length > 0
      ) {
        return candidate.trained_by_email;
      }
      return null;
    },
  },
});
</script>

